// ---------------------------------------------------------------------------
// Noise — fast, tileable value noise + fBm used by the procedural texture
// pipeline. All textures generated by this game are seeded and deterministic.
// ---------------------------------------------------------------------------

function hash2(ix, iy, seed) {
  let h = (seed ^ Math.imul(ix, 374761393) ^ Math.imul(iy, 668265263)) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  h ^= h >>> 16;
  return (h >>> 0) / 4294967296;
}

/** Tileable value noise. `period` = lattice size (integer >= 1). */
export function valueNoise(x, y, period, seed) {
  const xi = Math.floor(x), yi = Math.floor(y);
  const xf = x - xi, yf = y - yi;
  const u = xf * xf * (3 - 2 * xf), v = yf * yf * (3 - 2 * yf);
  const p = Math.max(1, period | 0);
  const x0 = ((xi % p) + p) % p, x1 = (x0 + 1) % p;
  const y0 = ((yi % p) + p) % p, y1 = (y0 + 1) % p;
  const a = hash2(x0, y0, seed), b = hash2(x1, y0, seed);
  const c = hash2(x0, y1, seed), d = hash2(x1, y1, seed);
  return a + (b - a) * u + (c - a) * v + (a - b - c + d) * u * v;
}

/**
 * Tileable fractal Brownian motion in [0,1].
 * Sample across texture as fbm(u * basePeriod, v * basePeriod, ...).
 */
export function fbm(x, y, basePeriod, seed, octaves = 4, gain = 0.5, lacunarity = 2) {
  let sum = 0, amp = 1, norm = 0, p = basePeriod;
  for (let o = 0; o < octaves; o++) {
    sum += amp * valueNoise(x * p, y * p, p, seed + o * 1013);
    norm += amp;
    amp *= gain;
    p = Math.max(1, Math.round(p * lacunarity));
  }
  return sum / norm;
}

/** Ridged variant — good for cracks / rocks. */
export function ridged(x, y, basePeriod, seed, octaves = 4) {
  let sum = 0, amp = 1, norm = 0, p = basePeriod;
  for (let o = 0; o < octaves; o++) {
    const n = 1 - Math.abs(valueNoise(x * p, y * p, p, seed + o * 733) * 2 - 1);
    sum += amp * n * n;
    norm += amp;
    amp *= 0.5;
    p = Math.max(1, Math.round(p * 2));
  }
  return sum / norm;
}

/** Random blob mask helper: soft circle with noisy edge. */
export function blobEdge(x, y, seed, wobble = 0.25) {
  const ang = Math.atan2(y - 0.5, x - 0.5);
  const r = Math.hypot(x - 0.5, y - 0.5);
  const n = fbm(Math.cos(ang) * 0.5 + 0.5, Math.sin(ang) * 0.5 + 0.5, 4, seed, 3);
  return r / (0.28 + n * wobble);
}
